INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2890512', 'Battle of Croix-des-Bouquets', 'The Battle of Croix-des-Bouquets took place during the Haitian Revolution.', 1792, 3, 22, NULL, NULL, NULL, 'day', '22 March 1792', 41, 'https://en.wikipedia.org/wiki/Battle_of_Croix-des-Bouquets'),
  ('Q2890742', 'Battle of Cap-Français', 'The Battle of Cap-Français took place from 20 to 22 June 1793 during the Haitian Revolution. It was originally a conflict between commissioners sent by the French Republican government, who were supported by rebellious slaves and free people of color, against the colony''s elite and white royalist slave owners, who sparked an uprising against the commissioners in the city, led to a military conflict between whites and coloreds within the city, to eventually lead to an attack by slaves throughout the city.', 1793, 6, 20, 1793, 6, 22, 'day', '20 June 1793 – 22 June 1793', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cap-Fran%C3%A7ais_(1793)'),
  ('Q3485993', 'Siege of Port-au-Prince', 'The siege of Port-au-Prince took place in April 1793 during the Haitian Revolution.', 1793, 4, 12, 1793, 4, 14, 'day', '12 April 1793 – 14 April 1793', 37, 'https://en.wikipedia.org/wiki/Siege_of_Port-au-Prince_(1793)'),
  ('Q2890666', 'Battle of Gonaïves', 'The Battle of Gonaïves took place during the Haitian Revolution.', 1794, 5, 5, NULL, NULL, NULL, 'day', '5 May 1794', 34, 'https://en.wikipedia.org/wiki/Battle_of_Gona%C3%AFves'),
  ('Q3403821', 'Capture of Fort-Dauphin', 'The capture of Fort-Dauphin was a bloodless encounter of the French Revolutionary Wars in which a Spanish expeditionary force under Admiral Gabriel de Aristizábal y Espinosa seized Fort-Dauphin (now Fort-Liberté), in Saint-Domingue, from France. The French garrison of about a thousand men, blockaded by land and sea, surrendered without firing a single shot.', 1794, 1, 28, 1794, 1, 29, 'day', '28 January 1794 – 29 January 1794', 34, 'https://en.wikipedia.org/wiki/Capture_of_Fort-Dauphin_(1794)'),
  ('Q4871314', 'Battle of Jean-Rabel', 'The Battle of Jean-Rabel consisted of two connected minor naval engagements of the French Revolutionary Wars and the Haitian Revolution. The first engagement saw an overwhelming British Royal Navy force consisting of two ships of the line attack and destroy a French Navy frigate in Moustique Inlet near the town of Jean-Rabel on the Northern coast of the French colony of Saint-Domingue (which later gained independence as Haiti).', 1797, 4, 15, 1797, 4, 21, 'day', '15 April 1797 – 21 April 1797', 34, 'https://en.wikipedia.org/wiki/Battle_of_Jean-Rabel'),
  ('Q3486058', 'Battle of Crête-à-Pierrot', 'The Battle of Crête-à-Pierrot was a major battle of the Saint-Domingue expedition that took place between 2 March and 24 March 1802 as part of the expedition''s efforts to retake the colony of Saint-Domingue from Toussaint Louverture''s control. The battle took place at the Crête-à-Pierrot fort ("Little Peter''s Crest;" in Haitian Creole Lakrèt-a-Pyewo), east of Saint-Marc on the valley of the Artibonite River.', 1802, 3, 4, 1802, 3, 24, 'day', '4 March 1802 – 24 March 1802', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cr%C3%AAte-%C3%A0-Pierrot'),
  ('Q2484240', 'Battle of Vertières', 'The Battle of Vertières (French: Bataille de Vertières; Haitian Creole: Batay Vètyè) was the last major battle of the Saint-Domingue expedition and the final phase of the Haitian Revolution. It was fought on 18 November 1803 between the rebel Indigenous Army under Jean Jacques Dessalines and François Capois and French forces under Donatien de Rochambeau, who were committed to regaining control of the island.', 1803, 11, 18, NULL, NULL, NULL, 'day', '18 November 1803', 56, 'https://en.wikipedia.org/wiki/Battle_of_Verti%C3%A8res'),
  ('Q3485996', 'Siege of Port-au-Prince', 'The siege of Port-au-Prince was an engagement that took place from October to November 1803 during the Haitian Revolution.', 1803, 10, NULL, 1803, 11, NULL, 'month', 'October 1803 – November 1803', 34, 'https://en.wikipedia.org/wiki/Siege_of_Port-au-Prince_(1803)'),
  ('Q3439047', 'War of Dominican Independence', 'The Dominican War of Independence (Spanish: Guerra de Independencia Dominicana) was a war of independence that began when the Dominican Republic declared independence from the Republic of Haiti on February 27, 1844 and ended on January 24, 1856. Before the war, the island of Hispaniola had been united for 22 years when the newly independent nation, previously known as the Captaincy General of Santo Domingo, was unified with the Republic of Haiti in 1822.', 1844, NULL, NULL, 1856, NULL, NULL, 'year', '1844–1856', 57, 'https://en.wikipedia.org/wiki/Dominican_War_of_Independence'),
  ('Q3298759', 'United States occupation of Haiti', 'The United States occupation of Haiti began on July 28, 1915, when 330 US Marines landed at Port-au-Prince, Haiti, after the National City Bank of New York (now Citibank) convinced US President Woodrow Wilson to take control of the country''s political and financial interests. The occupation took place following years of socioeconomic instability within Haiti that culminated in the lynching of Haitian President Vilbrun Guillaume Sam by a mob angered by his executions of political prisoners.', 1915, 7, 28, 1934, 8, 1, 'day', '28 July 1915 – 1 August 1934', 53, 'https://en.wikipedia.org/wiki/United_States_occupation_of_Haiti'),
  ('Q122302992', '1950 Haitian coup d''état', 'The 1950 Haitian coup d''état was a military overthrow of the president of Haiti Dumarsais Estimé by a three-man junta, the same participants in the 1946 coup d''état. The coup took place on May 10, 1950, as an army intervention whose motives were President Estimé''s attempt to extend his term of office and the subsequent political unrest.', 1950, 5, 10, NULL, NULL, NULL, 'day', '10 May 1950', 30, 'https://en.wikipedia.org/wiki/1950_Haitian_coup_d''%C3%A9tat'),
  ('Q3454868', '1961 Haitian presidential referendum', 'A presidential referendum was held in Haiti on 30 April 1961 alongside parliamentary elections. Voters were asked whether President François Duvalier should remain in office for a further six years.', 1961, 4, 30, NULL, NULL, NULL, 'day', '30 April 1961', 39, 'https://en.wikipedia.org/wiki/1961_Haitian_presidential_referendum'),
  ('Q3454872', 'Haitian constitutional referendum, 1985', 'A constitutional referendum was held in Haiti on 22 July 1985. The amendments to the new constitution would restore multi-party politics, although only on the condition that all parties swore allegiance to President Jean-Claude Duvalier, as well as re-confirming Duvalier as President for Life and allowing him to single-handedly appoint the Prime Minister and his successor.', 1985, 7, 22, NULL, NULL, NULL, 'day', '22 July 1985', 37, 'https://en.wikipedia.org/wiki/1985_Haitian_constitutional_referendum'),
  ('Q6312034', 'June 1988 Haitian coup d''état', 'The June 1988 Haitian coup d''état took place on 20 June 1988, when Henri Namphy overthrew Leslie Manigat. Manigat, who won the military-controlled 1988 general election, had taken office on 7 February.', 1988, 6, 20, NULL, NULL, NULL, 'day', '20 June 1988', 37, 'https://en.wikipedia.org/wiki/June_1988_Haitian_coup_d''%C3%A9tat'),
  ('Q7452125', 'September 1988 Haitian coup d''état', 'The September 1988 Haitian coup d''état took place on 18 September 1988, when a group of non-commissioned officers in the Haitian Presidential Guard overthrew General Henri Namphy and brought General Prosper Avril to power. Namphy had been a member of the National Council of Government from 1986 until the February 1988 inauguration of Leslie Manigat, who had won the military-controlled 1988 general election.', 1988, 9, 18, NULL, NULL, NULL, 'day', '18 September 1988', 34, 'https://en.wikipedia.org/wiki/September_1988_Haitian_coup_d''%C3%A9tat'),
  ('Q4586873', '1991 Haitian coup d''état', 'The 1991 Haitian coup d''état resulted in the overthrow of Jean-Bertrand Aristide, the democratically-elected president of Haiti, by a contingent of the Haitian military led by General Raoul Cédras and Chief of National Police Michel François. The coup began on 29 September 1991, when Haitian troops mutinied, launching a violent takeover that involved attacking Aristide''s residence, committing massacres, and ultimately forcing Aristide into exile in Venezuela.', 1991, 9, 29, NULL, NULL, NULL, 'day', '29 September 1991', 43, 'https://en.wikipedia.org/wiki/1991_Haitian_coup_d''%C3%A9tat'),
  ('Q1531692', 'Raboteau Massacre', 'The Raboteau massacre was an incident on April 22, 1994, in which military and paramilitary forces attacked the neighborhood of Raboteau Gonaïves, Haiti, the citizens of which had been participating in pro-Jean-Bertrand Aristide demonstrations. At least 23 residents were killed, though most groups estimated the true casualties to be higher.', 1994, 4, 22, NULL, NULL, NULL, 'day', '22 April 1994', 37, 'https://en.wikipedia.org/wiki/Raboteau_massacre'),
  ('Q2883469', '2004 Haitian coup d''état', 'A coup d''état in Haiti on 29 February 2004, following several weeks of conflict, resulted in the removal of President Jean-Bertrand Aristide from office. On 5 February, a rebel group, called the National Revolutionary Front for the Liberation and Reconstruction of Haiti, took control of Haiti''s fourth-largest city, Gonaïves.', 2004, 2, NULL, NULL, NULL, NULL, 'month', 'February 2004', 56, 'https://en.wikipedia.org/wiki/2004_Haitian_coup_d''%C3%A9tat'),
  ('Q43777', '2010 Haiti earthquake', 'A catastrophic magnitude 7.0 Mw earthquake struck Haiti at 16:53 local time (21:53 UTC) on Tuesday, 12 January 2010. The epicenter was near the town of Léogâne, Ouest department, approximately 25 kilometres (16 mi) west of Port-au-Prince, Haiti''s capital.', 2010, 1, 12, NULL, NULL, NULL, 'day', '12 January 2010', 84, 'https://en.wikipedia.org/wiki/2010_Haiti_earthquake'),
  ('Q56976152', '2018 Haiti earthquake', 'On October 6, 2018, at approximately 8:11 p.m, a magnitude 5.9 earthquake struck 19 kilometers northwest of Port-de-Paix, Haiti. The earthquake damaged structures and killed 18 people.', 2018, 10, 6, NULL, NULL, NULL, 'day', '6 October 2018', 50, 'https://en.wikipedia.org/wiki/2018_Haiti_earthquake'),
  ('Q60776533', '2018 Port-au-Prince massacre', 'On 13 November 2018, a massacre began within the La Saline slums of Port-au-Prince, Haiti. According to reports, at least 71 civilians were killed over a 24-hour period.', 2018, 11, 13, NULL, NULL, NULL, 'day', '13 November 2018', 34, 'https://en.wikipedia.org/wiki/2018_La_Saline_massacre'),
  ('Q61742338', 'Haitian crisis (2019–present)', 'The existing political, economic, and social crisis began with protests across cities in Haiti on 7 July 2018 in response to rising fuel prices. These protests gradually evolved into demands for the resignation of President Jovenel Moïse.', 2019, 2, 7, NULL, NULL, NULL, 'day', '7 February 2019', 53, 'https://en.wikipedia.org/wiki/Haitian_crisis_(2018%E2%80%93present)'),
  ('Q107442287', 'assassination of Jovenel Moïse', 'Jovenel Moïse, the 48th president of Haiti, was assassinated on 7 July 2021 at 1:00 am EDT (UTC−04:00) at his residence in Port-au-Prince. A group of 28 foreign mercenaries, mostly from Colombia, are alleged to be responsible for the killing.', 2021, 7, 7, NULL, NULL, NULL, 'day', '7 July 2021', 64, 'https://en.wikipedia.org/wiki/Assassination_of_Jovenel_Mo%C3%AFse'),
  ('Q108091634', '2021 Haiti earthquake', 'At 08:29:09 EDT on 14 August 2021, a magnitude 7.2 earthquake struck the Tiburon Peninsula of southern Haiti. It had a 10-kilometre-deep (6.2 mi) hypocenter near Petit-Trou-de-Nippes, approximately 150 kilometres (93 mi) west of the capital, Port-au-Prince.', 2021, 8, 14, NULL, NULL, NULL, 'day', '14 August 2021', 69, 'https://en.wikipedia.org/wiki/2021_Haiti_earthquake'),
  ('Q110106709', 'Cap-Haïtien fuel tanker explosion', 'On 14 December 2021, a fuel tank truck exploded in the Samari neighborhood of Cap-Haïtien, the capital city of the Haitian department of Nord. At least 90 people were killed and more than 120 were injured; many people were injured as a result of rushing towards the tanker, likely to collect some of its cargo, before the explosion occurred.', 2021, 12, 14, NULL, NULL, NULL, 'day', '14 December 2021', 51, 'https://en.wikipedia.org/wiki/Cap-Ha%C3%AFtien_fuel_tanker_explosion');
